//! Issue-1221 T0 tripwire: the Dory GGUF header census pins the upstream
//! format (arch `dory`, the explicit loop metadata, the untied 72-block
//! inventory). An upstream format event (the llama.cpp PR is UNMERGED; the
//! model card warns the GGUF format could change) MUST diff here — loud,
//! never a silent pass. The full per-tensor census record lives in
//! `tests/fixtures/i1221_dory_header_probe_q5km.txt` (generated by
//! `examples/i1221_dory_header_probe.rs --full`).
//!
//! Skips loud without the pinned file (env `I1221_DORY_GGUF`, else the
//! riir-train pin path); a skip is a deferral, never a green.

use std::path::PathBuf;

use riir_infer_core::gguf_loader::{GgufFile, GgmlType};

const PIN_FILE: &str = "NVIDIA-Nemotron-Labs-Dory1.0-4B-Q5_K_M.gguf";

fn model_path() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("I1221_DORY_GGUF") {
        let p = PathBuf::from(p);
        return p.exists().then_some(p);
    }
    // The repo's own sibling-layout default (the data-lane pin path).
    for base in ["../riir-train/data", "../../riir-train/data"] {
        let p = PathBuf::from(base).join(PIN_FILE);
        if p.exists() {
            return Some(p);
        }
    }
    None
}

#[test]
fn the_dory_header_matches_the_pinned_t0_census() {
    let Some(model) = model_path() else {
        panic!(
            "SKIP LOUD: pinned Dory GGUF not found (set I1221_DORY_GGUF); \
             the T0 tripwire needs the pin to adjudicate format drift"
        );
    };
    let file = GgufFile::open(&model).expect("header parse");

    // ── the arch key + the explicit loop metadata ──
    assert_eq!(
        file.metadata_string("general.architecture"),
        Some("dory"),
        "arch key drifted"
    );
    assert_eq!(file.metadata_u64("dory.block_count"), Some(72));
    assert_eq!(file.metadata_u64("dory.input_layer_count"), Some(16));
    assert_eq!(file.metadata_u64("dory.recurrent_layer_count"), Some(40));
    assert_eq!(file.metadata_u64("dory.output_layer_count"), Some(16));
    assert_eq!(file.metadata_u64("dory.num_loops"), Some(4));
    assert_eq!(
        file.metadata_string("dory.recurrent_kv_cache_mode"),
        Some("per_loop"),
        "the KV cache mode metadata drifted (the T0 per-loop verdict)"
    );
    assert_eq!(
        file.metadata_string("dory.layer_pattern"),
        Some("S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-S-S-S-*-"),
        "the 36-attention-block 3:1 SWA/full pattern drifted"
    );
    assert_eq!(file.metadata_f64("dory.attention.sliding_window"), Some(1024.0));

    // ── the inventory shape: 507 tensors, 72 blocks, interleaved ──
    assert_eq!(file.tensor_infos.len(), 507, "tensor count drifted");
    let mut attn_layers = Vec::new();
    let mut ffn_layers = Vec::new();
    let mut names_with_norm = 0usize;
    for info in &file.tensor_infos {
        if info.name.contains("norm") {
            names_with_norm += 1;
        }
        let rest = match info.name.strip_prefix("blk.") {
            Some(after) => after.split_once('.').unwrap().1,
            None => continue,
        };
        match rest {
            "attn_q.weight" => attn_layers.push(layer_of(&info.name)),
            "ffn_up.weight" => ffn_layers.push(layer_of(&info.name)),
            _ => {}
        }
    }
    assert_eq!(names_with_norm, 0, "nGPT normalizes — norm tensors must not appear");
    assert_eq!(attn_layers.len(), 36, "attn block count drifted");
    assert_eq!(ffn_layers.len(), 36, "ffn block count drifted");
    assert!(
        attn_layers.iter().all(|l| l % 2 == 0),
        "attn blocks must sit on even block indices"
    );
    assert!(
        ffn_layers.iter().all(|l| l % 2 == 1),
        "ffn blocks must sit on odd block indices"
    );

    // ── the untied verdict: repeated rows DIVERGE (byte 0) ──
    // The paper's "shared recurrent block" is shared at EXECUTION time
    // (blocks 16..=55 re-run num_loops times), never weight-tied in the
    // bytes. Pinned on representative stems, both quant classes.
    let untied_pairs: [(&str, usize, usize); 4] = [
        ("attn_q.weight", 16, 18),
        ("ffn_down.weight", 17, 19),
        ("attn_v.weight", 16, 18),
        ("residual_alpha.weight", 16, 17),
    ];
    for (stem, a, b) in untied_pairs {
        let sa = file
            .tensor_slice(&format!("blk.{a}.{stem}"))
            .unwrap_or_else(|| panic!("blk.{a}.{stem} missing"));
        let sb = file
            .tensor_slice(&format!("blk.{b}.{stem}"))
            .unwrap_or_else(|| panic!("blk.{b}.{stem} missing"));
        assert_ne!(
            sa, sb,
            "blk.{a}.{stem} == blk.{b}.{stem}: the checkpoint gained weight ties \
             (a different loop-sharing posture) — re-read before any loader work"
        );
    }

    // ── vocab tensors: untied BF16 pairs, the census's biggest rows ──
    for name in ["token_embd.weight", "output.weight"] {
        let info = file.tensor_info(name).unwrap_or_else(|| panic!("{name} missing"));
        assert_eq!(info.ggml_type, GgmlType::BF16, "{name} dtype drifted");
        assert_eq!(info.shape, vec![2560, 131072], "{name} shape drifted");
    }
    let output_scale = file
        .tensor_info("output_scale.weight")
        .expect("output_scale.weight missing");
    assert_eq!(output_scale.shape, vec![131072], "output_scale drifted");
}

fn layer_of(name: &str) -> usize {
    name.strip_prefix("blk.")
        .and_then(|after| after.split_once('.'))
        .and_then(|(idx, _)| idx.parse().ok())
        .expect("layered tensor name")
}
